def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]

    # Endgame: last few rounds, exploit if opponent generally cooperates,
    # otherwise defect to avoid being exploited.
    if n >= 96:
        coop = sum(1 for a in opp if a == 'C')
        if coop * 2 >= n:
            return 'D'
        return 'D'

    opp_def_total = sum(1 for a in opp if a == 'D')
    me_def_total = sum(1 for a in me if a == 'D')

    # Crush a sustained defector.
    if n >= 6:
        recent = opp[-6:]
        if sum(1 for a in recent if a == 'D') >= 5 and opp_def_total * 3 >= n * 2:
            return 'D'

    if n < 10:
        if last_opp == 'D':
            return 'D'
        return 'C'

    opp_def10 = sum(1 for a in opp[-10:] if a == 'D')
    me_def10 = sum(1 for a in me[-10:] if a == 'D')

    if opp_def10 >= 8:
        return 'D'

    # Opponent defected last round.
    if last_opp == 'D':
        if last_me == 'C':
            # Punish but forgive quickly if opponent mostly cooperates.
            coop_rate = (n - opp_def_total) / n
            if coop_rate > 0.75 and n >= 3 and opp[-2] == 'C' and opp[-3] == 'C':
                return 'C' if rng.random() < 0.5 else 'D'
            return 'D'
        else:
            # We defected too. Try to break the DD spiral if opponent
            # recently cooperated before the exchanges.
            if n >= 4 and opp[-2] == 'C' and opp[-3] == 'C':
                return 'C'
            if opp_def10 >= 6:
                return 'D'
            if rng.random() < 0.25:
                return 'C'
            return 'D'

    # Opponent cooperated last round.
    # If opponent is a near-pure cooperator, mostly cooperate but
    # probe occasionally to grab DC without triggering retaliation.
    if opp_def_total == 0 and n >= 8:
        if rng.random() < 0.08:
            return 'D'
        return 'C'
    if opp_def10 == 0 and n >= 8:
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    # If we've been defecting a lot, return to cooperation to avoid
    # locking into mutual defection.
    if me_def10 >= 5:
        return 'C'

    # If opponent is mostly cooperative, stay cooperative.
    if opp_def_total * 3 <= n:
        return 'C'

    # Mixed opponent: cooperate but occasionally defect to stay ahead.
    if opp_def_total * 2 >= n:
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    return 'C'
